// Dispatch decodes one event on wl_touch and calls the registered handlers.
func (o *Touch) Dispatch(event *wl.Event) {
	switch event.Opcode {
	case 0: // down
		serial := event.Uint32()
		time := event.Uint32()
		surfaceID := event.Uint32()
		id := event.Int32()
		x := event.Fixed()
		y := event.Fixed()
		for _, handler := range o.handlersForDown() {
			handler(serial, time, surfaceID, id, x, y)
		}
	case 1: // up
		serial := event.Uint32()
		time := event.Uint32()
		id := event.Int32()
		for _, handler := range o.handlersForUp() {
			handler(serial, time, id)
		}
	case 2: // motion
		time := event.Uint32()
		id := event.Int32()
		x := event.Fixed()
		y := event.Fixed()
		for _, handler := range o.handlersForMotion() {
			handler(time, id, x, y)
		}
	case 3: // frame
		for _, handler := range o.handlersForFrame() {
			handler()
		}
	case 4: // cancel
		for _, handler := range o.handlersForCancel() {
			handler()
		}
	case 5: // shape
		id := event.Int32()
		major := event.Fixed()
		minor := event.Fixed()
		for _, handler := range o.handlersForShape() {
			handler(id, major, minor)
		}
	case 6: // orientation
		id := event.Int32()
		orientation := event.Fixed()
		for _, handler := range o.handlersForOrientation() {
			handler(id, orientation)
		}
	default:
	}
}

