func (o *Output) Dispatch(event *wl.Event) {
	switch event.Opcode {
	case 0: // geometry
		x := event.Int32()
		y := event.Int32()
		physicalWidth := event.Int32()
		physicalHeight := event.Int32()
		subpixel := event.Int32()
		make := event.String()
		model := event.String()
		transform := event.Int32()
		for _, handler := range o.handlersForGeometry() {
			handler(x, y, physicalWidth, physicalHeight, subpixel, make, model, transform)
		}
	case 1: // mode
		flags := event.Uint32()
		width := event.Int32()
		height := event.Int32()
		refresh := event.Int32()
		for _, handler := range o.handlersForMode() {
			handler(flags, width, height, refresh)
		}
	case 2: // done
		for _, handler := range o.handlersForDone() {
			handler()
		}
	case 3: // scale
		factor := event.Int32()
		for _, handler := range o.handlersForScale() {
			handler(factor)
		}
	case 4: // name
		name := event.String()
		for _, handler := range o.handlersForName() {
			handler(name)
		}
	case 5: // description
		description := event.String()
		for _, handler := range o.handlersForDescription() {
			handler(description)
		}
	default:
	}
}

